from data_access.database import get_games, get_sessiesdef toon_menu():    print("\n=== Game Tracker ===")    print("1. Games tonen")    print("2. Sessies tonen")    print("0. Stoppen")    def toon_games():    print("\nGames:")    for game in get_games():        print(f"{game.id}. {game}")                           def toon_sessies():    print("\nSessies:")    for sessie in get_sessies():        print(f"{sessie.id}. {sessie}")                        def start():    while True:        toon_menu()        keuze = input("Maak een keuze: ")        if keuze == "1":            toon_games()        elif keuze == "2":            toon_sessies()        elif keuze == "0":            print("Tot ziens!")            break        else:            print("Ongeldige keuze, probeer opnieuw.")